// Assets/Editor/SceneRegistrar.cs
using System.Collections.Generic;
using UnityEditor;

namespace Overlink.Editor
{
    public static class SceneRegistrar
    {
        // Desired build order — edit here if the list changes.
        // `optional` scenes are skipped with a warning instead of aborting the whole registration when
        // they have not been built yet. The faction previews are generated by
        // Overlink > Scenes > Build All Faction Collections / Build Faction Matrix Preview, so a fresh
        // clone legitimately does not have them on disk.
        // Auth is first on purpose: it is the game's boot scene, and AuthFlowController.ShowAuthScene()
        // loads it BY NAME, which only resolves for a scene that is in build settings. Omitting it here is
        // not cosmetic - Register() rewrites the whole list, so a run of this menu silently dropped Auth from
        // builds and every signed-out launch threw. Keep it at index 0.
        private static readonly (string path, bool enabled, bool optional)[] Scenes =
        {
            ("Assets/Scenes/Auth.unity",           true, false),
            ("Assets/Scenes/MainMenu.unity",       true, false),
            ("Assets/Scenes/Gameplay.unity",       true, false),
            ("Assets/Scenes/Deckbuilder.unity",    true, false),
            ("Assets/Scenes/Collection.unity",     true, false),
            ("Assets/Scenes/Settings.unity",       true, false),
            ("Assets/Scenes/NetPresenceDemo.unity",true, false),
            ("Assets/Scenes/CardPresentationPreview.unity", true, false),
            ("Assets/Scenes/CardPresentationLegendaryPreview.unity", true, false),
            ("Assets/Scenes/CardCollectionPreview.unity", true, false),
            ("Assets/Scenes/CardCollectionPreview_FRTI.unity", true, true),
            ("Assets/Scenes/CardCollectionPreview_FPB.unity", true, true),
            ("Assets/Scenes/CardFrameMatrixPreview_Unit.unity", true, true),
            ("Assets/Scenes/CardFrameMatrixPreview_Ability.unity", true, true),
            ("Assets/Scenes/CardFrameMatrixPreview_Relay.unity", true, true),
            ("Assets/Scenes/CardFrameMatrixPreview_Protocol.unity", true, true),
            ("Assets/Scenes/SampleScene.unity",    false, false),
        };

        [MenuItem("Overlink/Register Scenes in Build Settings")]
        public static void Register()
        {
            var missing = new List<string>();
            var present = new List<(string path, bool enabled)>();
            foreach (var (path, enabled, optional) in Scenes)
            {
                if (AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(path) != null)
                {
                    present.Add((path, enabled));
                }
                else if (optional)
                {
                    UnityEngine.Debug.LogWarning(
                        "[SceneRegistrar] Optional scene not built yet, skipping: " + path);
                }
                else
                {
                    missing.Add(path);
                }
            }

            if (missing.Count > 0)
            {
                UnityEngine.Debug.LogError(
                    "[SceneRegistrar] Registration aborted; missing scene assets:\n" +
                    string.Join("\n", missing));
                return;
            }

            var list = new List<EditorBuildSettingsScene>();
            foreach (var (path, enabled) in present)
                list.Add(new EditorBuildSettingsScene(path, enabled));

            EditorBuildSettings.scenes = list.ToArray();

            var actual = EditorBuildSettings.scenes;
            if (actual.Length != list.Count)
            {
                UnityEngine.Debug.LogError(
                    $"[SceneRegistrar] Verification failed: expected {list.Count} scenes, got {actual.Length}.");
                return;
            }

            for (var i = 0; i < list.Count; i++)
            {
                if (actual[i].path != present[i].path || actual[i].enabled != present[i].enabled)
                {
                    UnityEngine.Debug.LogError(
                        $"[SceneRegistrar] Verification failed at index {i}: " +
                        $"expected {present[i].path} (enabled={present[i].enabled}), " +
                        $"got {actual[i].path} (enabled={actual[i].enabled}).");
                    return;
                }
            }

            UnityEngine.Debug.Log($"[SceneRegistrar] Build settings updated and verified ({list.Count} scenes).");
        }
    }
}
